var n=`0866-chicken-karahi`;var t=`world-0866`;var a=`PK`;var r=`south-asia`;var s=4;var g=53;var o={en:`Chicken Karahi`,ua:`Курка карахі`};var h={en:`Chicken Karahi is a Pakistan dish made with chicken thigh, ginger-garlic paste, tomato, serrano pepper. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Курка карахі, страва кухні країни Пакистан. Основні складники: куряче стегно, імбирно-часникова паста, помідор, перець серрано. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var d=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 15 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 15 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:15,i:[[`chicken-thigh`,860,`g`],[`canola-oil`,55,`ml`],[`ginger-garlic-paste`,33,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 27 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 27 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:27,i:[[`tomato`,540,`g`],[`serrano-pepper`,3,`pcs`],[`ground-cumin`,6,`g`],[`ground-coriander`,7,`g`],[`table-salt`,null,`to_taste`]]},{en:`Simmer the liquid and flavorings uncovered for about 8 minutes until reduced and concentrated.`,ua:`Уварюйте рідину з приправами без кришки приблизно 8 хвилин до насичення та загустіння.`,t:[`reducing-sauce`],m:8,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,22,`g`],[`ground-ginger`,20,`g`]]}];var u={slug:n,id:t,country:`PK`,region:r,servings:4,minutes:53,title:o,text:h,steps:d};export{a as country,u as default,t as id,g as minutes,r as region,s as servings,n as slug,d as steps,h as text,o as title};